    ~InstrumentEditorPanel() override {rememberPosition();juce::Desktop::getInstance().removeFocusChangeListener(this);stopTimer();chooser.reset();if(worker.joinable())worker.join();}
    void activate(){if(!loadedSources.empty()){if(p().samples.empty()&&draft.programs.empty()&&draft.savedFile==juce::File{}){if(auto* active=findPreset(loadedSources,currentSourceCode))p().format=juce::File(active->path).hasFileExtension("sfz")?Format::sfz:Format::sf2;}page=0;lastFocus=10;}showPage(page,false);auto* c=rememberedControl();focus(*c);say(*c,c==&zoneCell?zoneContext()+", "+zoneText():c==&sampleCell?sampleText():c==&modCell?modText():c==&projectBank?projectBank.getText():c==&projectProgram?projectProgram.getText():c->getTitle());refreshPreview();startTimerHz(5);}
    void paint(juce::Graphics& g) override {
        g.fillAll(juce::Colour(0xff202429));
        if(picking&&!pickerZones.empty()&&!gridBounds.isEmpty()){g.setFont(juce::FontOptions(15.0f));const int first=(pickerIndex/8)*8;for(int j=first;j<std::min(first+8,int(pickerZones.size()));++j){const auto& z=p().zones[size_t(pickerZones[size_t(j)])];auto cell=juce::Rectangle<int>(gridBounds.getX(),gridBounds.getY()+(j-first)*30,gridBounds.getWidth(),30).reduced(2);g.setColour(j==pickerIndex?juce::Colour(0xff3d536c):juce::Colour(0xff2b3036));g.fillRoundedRectangle(cell.toFloat(),3);g.setColour(juce::Colours::white);g.drawFittedText("Zone "+juce::String(pickerZones[size_t(j)]+1)+", keys "+juce::String(z.low)+"–"+juce::String(z.high)+", velocity "+juce::String(z.lowVel)+"–"+juce::String(z.highVel),cell.reduced(5,1),juce::Justification::centredLeft,1);}return;}
        if(page!=2||p().zones.empty()||gridBounds.isEmpty())return;
        const int first=(column/16)*16,w=gridBounds.getWidth()/2,h=gridBounds.getHeight()/8;
        auto params=parameters();g.setFont(juce::FontOptions(13.0f));
        for(int i=first;i<std::min(first+16,int(params.size()));++i){int k=i-first;auto cell=juce::Rectangle<int>(gridBounds.getX()+(k/8)*w,gridBounds.getY()+(k%8)*h,w,h).reduced(2);
            g.setColour(i==column?juce::Colour(0xff3d536c):juce::Colour(0xff2b3036));g.fillRoundedRectangle(cell.toFloat(),3);g.setColour(juce::Colours::white);g.drawFittedText(parameterText(i),cell.reduced(5,1),juce::Justification::centredLeft,1);}
    }
    void resized() override {
        auto r=getLocalBounds().reduced(12);gridBounds={};
        r.removeFromTop(8);message.setBounds(r.removeFromTop(44));details.setBounds(r.removeFromTop(50));r.removeFromTop(8);
        closeButton.setBounds(r.removeFromBottom(40).removeFromRight(220));
        auto put=[&](juce::Component& c){c.setBounds(r.removeFromTop(40).reduced(0,3));};
        if(confirmAction){put(cancelButton);put(confirmButton);return;}
        if(sourcePicking){put(loadedPicker);return;}
        if(page==0){put(format);put(name);put(newProject);put(openProject);put(newInstrument);}
        else if(page==1){if(picking){put(zonePicker);gridBounds=r;}else{put(sampleCell);put(importButton);put(mappingMode);put(chromaticStart);put(removeSample);put(addZoneButton);}}
        else if(page==2){put(zoneCell);auto actions=r.removeFromBottom(40);duplicateZone.setBounds(actions.removeFromLeft(actions.getWidth()/2).reduced(2));deleteZone.setBounds(actions.reduced(2));gridBounds=r;}
        else if(page==3||page==4){if(page==4)put(sourceCell);put(modCell);}
        else {put(projectBank);put(projectProgram);put(saveButton);put(saveAsButton);put(exportButton);}
    }
private:
    Draft& draft;std::function<void()> closeAction;
    std::function<void(const Project&,int)> previewAction;std::function<juce::String()> statusAction;std::function<void()> panicAction;
    int rawSample=-1;juce::String previousPreviewStatus;
    void refreshPreview(){rawSample=-1;previewAction(p(),-1);}
    void auditionSample(){if(p().samples.empty())return;if(rawSample==sampleIndex){refreshPreview();notify("Mapped MIDI preview");}else{rawSample=sampleIndex;previewAction(p(),rawSample);notify("Audition sample "+lsfx::instrument::js(p().samples[size_t(sampleIndex)].name));}}
    void timerCallback() override {auto status=statusAction();if(status==previousPreviewStatus)return;previousPreviewStatus=status;if(status=="Preview: sample ended"&&rawSample>=0){refreshPreview();return;}if(status.startsWith("Preview error")){if(!busy&&!chooser)notify(status);} }
    Button loadedPicker,format,newProject,openProject,sampleCell,zonePicker,modCell,sourceCell,importButton,mappingMode,chromaticStart,removeSample,addZoneButton,zoneCell,duplicateZone,deleteZone,saveButton,saveAsButton,exportButton,newInstrument,confirmButton,cancelButton,closeButton;
    Keyed<juce::ComboBox> projectBank,projectProgram;std::function<void()> confirmAction;juce::Component* confirmOrigin=nullptr;int bankIndex=0,programIndex=0;
    Keyed<juce::TextEditor> name;
    juce::Label message,details;juce::Rectangle<int> gridBounds;
    int page=0,sampleIndex=0,zoneIndex=0,column=0,modeIndex=0,startNote=60,stepIndex=0,lastFocus=10;
    bool busy=false,picking=false;int pickerIndex=0,modSource=129,modRow=0,modColumn=0;
    std::vector<int> pickerZones;
    std::vector<Preset> loadedSources,sourceChoices;int currentSourceCode=-1,sourceChoiceIndex=0;bool sourcePicking=false;
    std::vector<Project>& undo=draft.undo;std::vector<Project>& redo=draft.redo;std::optional<Zone>& clipboard=draft.clipboard;
    void globalFocusChanged(juce::Component* c) override {if(c&&isParentOf(c)&&c->getExplicitFocusOrder()>0)lastFocus=c->getExplicitFocusOrder();}
    void rememberPosition(){if(confirmAction&&confirmOrigin)lastFocus=confirmOrigin->getExplicitFocusOrder();draft.position={page,sampleIndex,zoneIndex,column,modeIndex,startNote,stepIndex,lastFocus,modSource,modRow,modColumn,bankIndex,programIndex};}
    juce::Component* rememberedControl(){for(int i=0;i<getNumChildComponents();++i){auto* c=getChildComponent(i);if(c->isVisible()&&c->getWantsKeyboardFocus()&&c->getExplicitFocusOrder()==lastFocus)return c;}return &primary();}
    std::unique_ptr<juce::FileChooser> chooser;std::thread worker;
    static constexpr int steps[]={1,5,10,20,50,100,500,1000,10000};
    template<class C> void setup(Keyed<C>& c,const juce::String& text,int order){c.setName(text);c.setTitle(text);c.setExplicitFocusOrder(order);c.setWantsKeyboardFocus(true);c.keyHandler=[this](const juce::KeyPress& k,juce::Component* origin){return handle(k,origin);};addAndMakeVisible(c);}
    void setup(Button& b,const juce::String& text,int order,std::function<void()> action){setup<juce::TextButton>(b,text,order);b.setButtonText(text);b.onClick=[this,action=std::move(action)]{if(!busy&&!chooser)action();};}
    static void label(Button& b,const juce::String& text){if(b.getButtonText()!=text){b.setButtonText(text);b.setName(text);b.setTitle(text);}}
    void say(juce::Component& c,const juce::String& text){speak(c,text);}
    void focus(juce::Component& c){if(c.isShowing()){lastFocus=c.getExplicitFocusOrder();c.grabKeyboardFocus();}}
    juce::Component& primary(){if(page==0)return sourcePicking?loadedPicker:format;if(page==1)return picking?zonePicker:sampleCell;if(page==2)return zoneCell;if(page==3)return modCell;if(page==4)return sourceCell;return projectBank;}
    void notify(const juce::String& text){message.setText(text,juce::dontSendNotification);message.setTitle(text);if(auto* c=juce::Component::getCurrentlyFocusedComponent();c&&isParentOf(c))say(*c,text);}
    void focusAfterDialog(){focus(*rememberedControl());juce::Component::SafePointer<InstrumentEditorPanel> safe(this);juce::Timer::callAfterDelay(150,[safe]{if(auto* p=safe.getComponent();p&&p->isShowing()&&p->getPeer()&&p->getPeer()->isFocused()&&!p->chooser){auto* c=juce::Component::getCurrentlyFocusedComponent();if(!c||!p->isParentOf(c))p->focus(*p->rememberedControl());}});}
    void showPage(int n,bool grab=true){if(busy&&grab)return;if(n!=1&&rawSample>=0)refreshPreview();if(n==4&&page==2&&!sfzMode()){auto params=parameters();if(column>=0&&column<int(params.size())&&(params[size_t(column)]->member==&Zone::lowVel||params[size_t(column)]->member==&Zone::highVel))modSource=2;}else if(n==4&&page==3){auto rows=filteredMods();if(!rows.empty())modSource=p().zones[size_t(zoneIndex)].mods[size_t(rows[size_t(std::clamp(modRow,0,int(rows.size())-1))])].source&255;}picking=false;sourcePicking=false;loadedPicker.setVisible(false);page=juce::jlimit(0,5,n);
        std::array<juce::Component*,5> a{&format,&name,&newProject,&openProject,&newInstrument};std::array<juce::Component*,6> b{&sampleCell,&importButton,&mappingMode,&chromaticStart,&removeSample,&addZoneButton};std::array<juce::Component*,3> c{&zoneCell,&duplicateZone,&deleteZone};std::array<juce::Component*,5> d{&projectBank,&projectProgram,&saveButton,&saveAsButton,&exportButton};for(auto* p:a)p->setVisible(page==0);for(auto* p:b)p->setVisible(page==1);for(auto* p:c)p->setVisible(page==2);for(auto* p:d)p->setVisible(page==5);zonePicker.setVisible(false);modCell.setVisible(page==3||page==4);sourceCell.setVisible(page==4);updateAll();resized();if(grab){focus(primary());say(primary(),page==0?format.getButtonText():page==1?sampleText():page==2?zoneContext()+", "+zoneText():page==3?modText():page==4?sourceCell.getButtonText():projectBank.getText());}}
    Project& p(){return draft.project;}const Project& p() const{return draft.project;}
    juce::String sampleText() const {if(p().samples.empty())return "No samples. Enter to import";auto& s=p().samples[size_t(sampleIndex)];return "Sample "+juce::String(sampleIndex+1)+" of "+juce::String(int(p().samples.size()))+", "+lsfx::instrument::js(s.name)+", Root "+juce::String(s.root);}
    using Param=lsfx::instrument::ZoneParam;
    std::vector<const Param*> parameters() const {std::vector<const Param*> out;for(const auto& param:lsfx::instrument::zoneParams)if((!param.sfzOnly||p().format==Format::sfz)&&(!param.sf2Only||p().format==Format::sf2))out.push_back(&param);return out;}
    juce::String zoneContext() const {return p().zones.empty()?juce::String("No zones"):"Zone "+juce::String(zoneIndex+1)+" of "+juce::String(int(p().zones.size()));}
    juce::String parameterText(int i) const {
        if(p().zones.empty())return "No zones";
        const auto params=parameters();if(i<0||i>=int(params.size()))return {};
        const auto& param=*params[size_t(i)];const auto& z=p().zones[size_t(zoneIndex)];const int n=z.*param.member;juce::String v;
        if(param.member==&Zone::sample)v=lsfx::instrument::js(p().samples[size_t(n)].name);
        else if(param.member==&Zone::loopMode){static const char* modes[]={"Off","Continuous","Sustain","One shot"};v=modes[std::clamp(n,0,3)];}
        else if(param.member==&Zone::trigger){static const char* names[]={"Attack","Release","First","Legato"};v=names[n];}
        else if(param.member==&Zone::offMode){static const char* names[]={"Fast","Normal","Time"};v=names[n];}
        else if(param.member==&Zone::filterType){static const char* names[]={"Low pass 2 pole","High pass 2 pole","Band pass 2 pole","Band reject 2 pole","Low pass 1 pole","High pass 1 pole"};v=names[n];}
        else if(param.member==&Zone::sustainSwitch)v=n?"On":"Off";
        else if(param.member==&Zone::notePolyphony&&n==0)v="Unlimited";
        else if(juce::String(param.unit)=="0.1 percent")v=juce::String(n/10.0,1)+" percent";
        else if(param.member==&Zone::pan)v=n==0?juce::String("Center"):juce::String(std::abs(n))+" percent "+(n<0?"left":"right");
        else if((param.member==&Zone::endFrame||param.member==&Zone::loopEnd)&&n<0)v="End";
        else if((param.member==&Zone::choke||param.member==&Zone::chokeTarget)&&n==0)v="Off";
        else if(juce::String(param.unit)=="mHz")v=juce::String(n/1000.0,3)+" Hz";
        else if(juce::String(param.unit)=="0.01 dB")v=juce::String(n/100.0,2)+" dB";
        else if(juce::String(param.unit)=="0.1 dB")v=juce::String(n/10.0,1)+" dB";
        else {v=juce::String(n);if(*param.unit)v+=" "+juce::String(param.unit);}
        return juce::String(param.name)+", "+v;
    }
    juce::String zoneText() const {return p().zones.empty()?juce::String("No mapping zones. Import audio on F2"):parameterText(column);}
    void syncSample(){if(!p().zones.empty())sampleIndex=p().zones[size_t(std::clamp(zoneIndex,0,int(p().zones.size())-1))].sample;}
    
    void moveZone(int d,juce::Component* origin){if(p().zones.empty())return;int n=std::clamp(zoneIndex+d,0,int(p().zones.size())-1);if(n==zoneIndex)return;zoneIndex=n;if(rawSample>=0)refreshPreview();updateAll();say(*origin,zoneContext()+", "+(page==2?zoneText():page==3||page==4?modText():lsfx::instrument::js(p().samples[size_t(p().zones[size_t(zoneIndex)].sample)].name)));}
    void updateAll(){sampleIndex=juce::jlimit(0,juce::jmax(0,int(p().samples.size())-1),sampleIndex);zoneIndex=juce::jlimit(0,juce::jmax(0,int(p().zones.size())-1),zoneIndex);column=juce::jlimit(0,int(parameters().size())-1,column);
        updateModLabels();label(format,p().format==Format::sf2?"Format: SF2":"Format: SFZ");label(sampleCell,sampleText());label(zoneCell,zoneText());
        static const char* modes[]={"Layer","Chromatic","Multisample","Velocity layers"};label(mappingMode,juce::String("Import mapping: ")+modes[modeIndex]);label(chromaticStart,"Chromatic start note: "+juce::String(startNote));if(page==5)updateProgramList();
        details.setText((page>=1?zoneContext()+". ":juce::String{})+juce::String(int(p().samples.size()))+" unique samples, "+juce::String(int(draft.programs.size()))+" saved programs, "+juce::String(int(p().zones.size()))+" zones, "+juce::String(double(p().bytes())/1048576.0,2)+" MiB source audio"+(draft.dirty?". Unsaved changes.":"."),juce::dontSendNotification);repaint();
    }
    void pruneHistory(){while(undo.size()>24)undo.erase(undo.begin());while(redo.size()>24)redo.erase(redo.begin());auto total=[&]{std::set<const lsfx::instrument::Blob*> seen;size_t n=0;auto scan=[&](const Project& q){for(auto& s:q.samples)if(s.bytes&&seen.insert(s.bytes.get()).second)n+=s.bytes->size();};scan(p());for(auto& item:draft.programs)scan(item.second);for(auto& q:undo)scan(q);for(auto& q:redo)scan(q);return n;};while(total()>lsfx::instrument::maxProjectBytes){if(!undo.empty())undo.erase(undo.begin());else if(!redo.empty())redo.erase(redo.begin());else break;}}
    void snapshot(){undo.push_back(p());redo.clear();pruneHistory();}
    void changed(){draft.dirty=true;pruneHistory();updateAll();refreshPreview();}
    void history(bool forward){auto& a=forward?redo:undo;auto& b=forward?undo:redo;if(a.empty())return;if(!draft.programs.empty()&&a.back().format!=p().format){notify("Cannot change the format of a project containing saved programs");return;}b.push_back(p());p()=std::move(a.back());a.pop_back();name.setText(lsfx::instrument::js(p().name),false);changed();notify(forward?"Redo":"Undo");}
    void toggleFormat(){if(!draft.programs.empty()){notify("Project format cannot change while it contains saved programs");return;}snapshot();p().format=p().format==Format::sf2?Format::sfz:Format::sf2;for(auto& z:p().zones){z.nativeGenerators.clear();if(p().format==Format::sf2){if(z.loopMode==3)z.loopMode=0;z.level=-4*lsfx::instrument::sf2FileAttenuation(z.level);}}changed();say(format,format.getButtonText());}
    void changeMode(int d){const int n=juce::jlimit(0,3,modeIndex+d);if(n==modeIndex)return;modeIndex=n;updateAll();say(mappingMode,mappingMode.getButtonText());}
    void changeStart(int d){const int n=juce::jlimit(0,127,startNote+d);if(n==startNote)return;startNote=n;updateAll();say(chromaticStart,chromaticStart.getButtonText());}
    void newDraft(){if(draft.dirty&&(!p().samples.empty()||!draft.programs.empty()||draft.savedFile!=juce::File{})){notify("Save the current project before creating a new one");return;}auto fmt=p().format;draft=Draft{};p().format=fmt;undo.clear();redo.clear();clipboard.reset();sampleIndex=zoneIndex=column=bankIndex=programIndex=0;name.setText(lsfx::instrument::js(p().name),false);updateAll();refreshPreview();notify("New empty instrument project");}
    void closeEditor(){if(busy||chooser)return;rememberPosition();auto callback=closeAction;if(callback)callback();}
    void deleteSample(){if(p().samples.empty())return;auto copy=p();if(!copy.removeSample(size_t(sampleIndex))){notify("Sample is used by a mapping zone. Delete its zones first");return;}snapshot();p()=std::move(copy);changed();notify(sampleText());}
    void addZone(){if(p().samples.empty())return;if(p().zones.size()>=lsfx::instrument::maxZones){notify("Zone limit reached");return;}snapshot();p().addZones({sampleIndex},Mapping::layer);zoneIndex=int(p().zones.size())-1;column=0;changed();showPage(2);}
    void duplicate(){if(p().zones.empty())return;if(p().zones.size()>=lsfx::instrument::maxZones){notify("Zone limit reached");return;}auto z=p().zones[size_t(zoneIndex)];snapshot();p().zones.insert(p().zones.begin()+zoneIndex+1,z);++zoneIndex;changed();focus(zoneCell);say(zoneCell,zoneText());}
    void deleteCurrentZone(){if(p().zones.empty())return;snapshot();p().zones.erase(p().zones.begin()+zoneIndex);changed();focus(zoneCell);say(zoneCell,zoneText());}
    void enterSample(){if(p().samples.empty()){browseImport();return;}pickerZones.clear();for(int i=0;i<int(p().zones.size());++i)if(p().zones[size_t(i)].sample==sampleIndex)pickerZones.push_back(i);if(pickerZones.empty()){notify("No zones for this sample. Insert to add zone");return;}if(pickerZones.size()==1){zoneIndex=pickerZones[0];showPage(2);return;}auto it=std::find(pickerZones.begin(),pickerZones.end(),zoneIndex);pickerIndex=it==pickerZones.end()?0:int(it-pickerZones.begin());picking=true;for(auto* c:std::array<juce::Component*,6>{&sampleCell,&importButton,&mappingMode,&chromaticStart,&removeSample,&addZoneButton})c->setVisible(false);zonePicker.setVisible(true);resized();focus(zonePicker);announcePicker();}
    void announcePicker(){const auto i=pickerZones[size_t(pickerIndex)];const auto& z=p().zones[size_t(i)];auto text="Zone "+juce::String(i+1)+", "+juce::String(pickerIndex+1)+" of "+juce::String(int(pickerZones.size()))+", keys "+juce::String(z.low)+" to "+juce::String(z.high)+", velocity "+juce::String(z.lowVel)+" to "+juce::String(z.highVel);label(zonePicker,text);repaint();say(zonePicker,text);}
    void acceptZone(){if(!picking||pickerZones.empty())return;zoneIndex=pickerZones[size_t(pickerIndex)];showPage(2);}
    using Mod=lsfx::instrument::Modulation;
    bool sfzMode()const{return p().format==Format::sfz;}
    int currentDestination()const{auto params=parameters();if(column<0||column>=int(params.size()))return -1;for(auto& d:lsfx::instrument::modDestinations)if(std::string(d.key)==params[size_t(column)]->key&&(!sfzMode()||d.sfzOpcode))return d.id;return -1;}
    std::vector<int> sources(bool secondary=false)const{std::vector<int> a;if(!sfzMode()){if(secondary)a.push_back(0);for(int n:{2,3,10,13,14,16})a.push_back(n);}for(int i=1;i<=119;++i)if(lsfx::instrument::validCC(i))a.push_back(128+i);return a;}
